cat <<'EOF' > test/controllers/pwa_controller_test.rb
require "test_helper"

class PwaControllerTest < ActionDispatch::IntegrationTest
  setup do
    sign_in_as :david
  end

  test "service worker fetches storage with CORS mode by default" do
    untenanted { get "/service-worker.js" }

    assert_response :success
    assert_match 'fetchOptions: { mode: "cors" }', response.body
  end

  test "service worker omits CORS fetch mode when disabled" do
    switch_env "SERVICE_WORKER_CORS_ENABLED", "false" do
      untenanted { get "/service-worker.js" }
    end

    assert_response :success
    assert_no_match(/mode: "cors"/, response.body)
  end

  test "service worker handles push and notificationclick events" do
    untenanted { get "/service-worker.js" }

    assert_response :success
    assert_match 'self.addEventListener("push"', response.body
    assert_match 'self.addEventListener("notificationclick"', response.body
    assert_match "self.registration.showNotification(title, options)", response.body
  end

  private
    def switch_env(key, value)
      old, ENV[key] = ENV[key], value
      yield
    ensure
      ENV[key] = old
    end
end
EOF

cat <<'EOF' > test/controllers/notifications/settings_controller_test.rb
require "test_helper"

class Notifications::SettingsControllerTest < ActionDispatch::IntegrationTest
  setup do
    @user = users(:david)

    sign_in_as @user
  end

  test "show" do
    get notifications_settings_path

    assert_response :success
    assert_select "section[data-controller='notifications'][data-notifications-subscriptions-url-value='#{user_push_subscriptions_path(@user)}']"
    assert_select "meta[name='vapid-public-key'][content='#{Rails.configuration.x.vapid.public_key}']"
  end

  test "show uses VAPID_PUBLIC_KEY from ENV when set" do
    old_key, ENV["VAPID_PUBLIC_KEY"] = ENV["VAPID_PUBLIC_KEY"], "custom-env-vapid-public-key"
    begin
      get notifications_settings_path

      assert_response :success
      assert_select "meta[name='vapid-public-key'][content='custom-env-vapid-public-key']"
    ensure
      ENV["VAPID_PUBLIC_KEY"] = old_key
    end
  end

  test "show as JSON" do
    get notifications_settings_path, as: :json
    assert_response :success

    assert_equal @user.settings.bundle_email_frequency, @response.parsed_body["bundle_email_frequency"]
  end

  test "update as JSON" do
    assert_changes -> { @user.reload.settings.bundle_email_frequency }, from: "never", to: "every_few_hours" do
      put notifications_settings_path, params: { user_settings: { bundle_email_frequency: "every_few_hours" } }, as: :json
    end

    assert_response :no_content
  end

  test "update email frequency" do
    assert_changes -> { @user.reload.settings.bundle_email_frequency }, from: "never", to: "every_few_hours" do
      put notifications_settings_path, params: { user_settings: { bundle_email_frequency: "every_few_hours" } }
    end

    assert_redirected_to notifications_settings_path
    assert_equal "Settings updated", flash[:notice]
  end
end
